-- 2.查询订单支付信息         结算状态( 0 未结算 1已结算 2失败 3取消)
-- pay_provider:0元(0), alipay(3), wechat(4), paypal(5), card_tree(6),venmo(7), alipay_citcon(8), apple_tree(9),card_stripe(10),apple_stripe(11),             cashapp(12), wechat-upi(13), alipay-upi(14)
        select a.charge_type,a.settlement,a.settlement_amount,
        a.* from yamibuy_payment.payment_charge a where a.purchase_id = @purchase_id;
-- 3. 支付拆单表   状态( 10初始化  20授权；40失败；50取消；51取消中;60成功)
  select a.auth_type,a.status,a.* from yamibuy_payment.payment_charge_order a where a.purchase_id = @purchase_id;
-- 4. 授信支付log表  type(1-成功 2-取消 3-取消中 4-失败)
  select * from yamibuy_payment.payment_charge_order_log where purchase_id = @purchase_id;

